const INK = '#28256c';
// Reference-pixel space of the 560x1300 packshots -> icon units (bottle 1294 px tall = 215 units).
const PX = 'translate(53.31 18.83) scale(.166151)';

// Fruit art, drawn in packshot pixels inside the PX group.
const n = (v) => Math.round(v * 100) / 100;
const pol = (cx, cy, r, a) => `${n(cx + Math.cos(a) * r)} ${n(cy + Math.sin(a) * r)}`;
const sector = (cx, cy, r, a0, a1) => `M${cx} ${cy}L${pol(cx, cy, r, a0)}A${r} ${r} 0 ${a1 - a0 > Math.PI ? 1 : 0} 1 ${pol(cx, cy, r, a1)}Z`;
const ring = (k, f) => Array.from({length: k}, (_, i) => f(i, i * 2 * Math.PI / k)).join('');
// Each fruit: a base tone, a shadow side (lower right, light comes from the upper left) and a highlight.
const banana = (cx, cy, r, rot = 0) => `<g transform="rotate(${rot} ${cx} ${cy})"><ellipse cx="${cx}" cy="${cy}" rx="${r}" ry="${n(r * .92)}" fill="#cdb46c"/><ellipse cx="${n(cx - r * .04)}" cy="${n(cy - r * .05)}" rx="${n(r * .91)}" ry="${n(r * .83)}" fill="#efdfae"/><ellipse cx="${n(cx - r * .12)}" cy="${n(cy - r * .13)}" rx="${n(r * .7)}" ry="${n(r * .62)}" fill="#fcf5df"/>${ring(3, (i, a) => `<path d="M${pol(cx, cy, r * .3, a + .5)}L${pol(cx, cy, r * .3, a + .5 + Math.PI)}" stroke="#d9c07a" stroke-width="${n(r * .07)}" stroke-linecap="round"/>`)}${ring(6, (i, a) => `<circle cx="${pol(cx, cy, r * .2, a)}" r="${n(r * .045)}" fill="#a8925a"/>`).replace(/cx="([\d.-]+) ([\d.-]+)"/g, 'cx="$1" cy="$2"')}</g>`;
const mango = (cx, cy, rx, ry, rot = 0) => `<g transform="rotate(${rot} ${cx} ${cy})"><ellipse cx="${cx}" cy="${cy}" rx="${rx}" ry="${ry}" fill="#8e1a2e"/><ellipse cx="${n(cx + rx * .03)}" cy="${n(cy - ry * .04)}" rx="${n(rx * .96)}" ry="${n(ry * .95)}" fill="#d23f4a"/><ellipse cx="${n(cx - rx * .05)}" cy="${n(cy + ry * .03)}" rx="${n(rx * .9)}" ry="${n(ry * .89)}" fill="#e7861c"/><ellipse cx="${n(cx - rx * .09)}" cy="${n(cy - ry * .01)}" rx="${n(rx * .83)}" ry="${n(ry * .81)}" fill="${ref('mango')}"/><ellipse cx="${n(cx - rx * .38)}" cy="${n(cy - ry * .36)}" rx="${n(rx * .26)}" ry="${n(ry * .16)}" fill="#fff" opacity=".22" transform="rotate(-30 ${n(cx - rx * .38)} ${n(cy - ry * .36)})"/></g>`;
const MANGO_DEF = '<radialGradient id="__ID__mango" cx=".38" cy=".36" r=".7"><stop stop-color="#fde26a"/><stop offset=".55" stop-color="#f9c23a"/><stop offset="1" stop-color="#f19f26"/></radialGradient>';
const kiwi = (cx, cy, r) => `<circle cx="${cx}" cy="${cy}" r="${r}" fill="#4e3818"/><circle cx="${cx}" cy="${cy}" r="${n(r * .92)}" fill="#5a8e1c"/><circle cx="${n(cx - r * .05)}" cy="${n(cy - r * .05)}" r="${n(r * .84)}" fill="#82b82a"/><circle cx="${n(cx - r * .14)}" cy="${n(cy - r * .16)}" r="${n(r * .46)}" fill="#a8d24c" opacity=".75"/><path d="${ring(18, (i, a) => `M${pol(cx, cy, r * .52, a)}L${pol(cx, cy, r * .8, a)}`)}" stroke="#c6e27a" stroke-width="2" opacity=".55"/>${ring(18, (i, a) => `<ellipse cx="${n(cx + Math.cos(a) * r * .41)}" cy="${n(cy + Math.sin(a) * r * .41)}" rx="${n(r * .032)}" ry="${n(r * .085)}" transform="rotate(${n(a * 180 / Math.PI + 90)} ${n(cx + Math.cos(a) * r * .41)} ${n(cy + Math.sin(a) * r * .41)})" fill="#1b220c"/>`)}<ellipse cx="${cx}" cy="${cy}" rx="${n(r * .27)}" ry="${n(r * .22)}" fill="#edefc6"/>`;
// Orange slice: rind, pith, ten segments with their membranes; half=true keeps only the lower half (a half slice).
const orange = (cx, cy, r, rot = 0, half = false) => {
  const a0 = half ? 0 : -Math.PI, k = half ? 5 : 10, sp = Math.PI / 5;
  const disc = (rr, f, dx = 0) => half ? `<path d="${sector(n(cx + dx), n(cy + dx), rr, 0, Math.PI)}" fill="${f}"/>` : `<circle cx="${n(cx + dx)}" cy="${n(cy + dx)}" r="${rr}" fill="${f}"/>`;
  return `<g transform="rotate(${rot} ${cx} ${cy})">${disc(r, '#d9660a')}${disc(n(r * .96), '#f48e1e', -r * .03)}${disc(n(r * .88), '#fde4ac')}${Array.from({length: k}, (_, i) => `<path d="${sector(cx, cy, n(r * .82), n(a0 + i * sp + .05), n(a0 + (i + 1) * sp - .05))}" fill="${i % 2 ? '#f7a01e' : '#fab232'}"/>`).join('')}<circle cx="${cx}" cy="${cy}" r="${n(r * .1)}" fill="#fde4ac"/><path d="${sector(cx, cy, n(r * .8), half ? 2.2 : 3.4, half ? 2.9 : 4.3)}" fill="#fff" opacity=".22"/></g>`;
};
const pineapple = (cx, cy, r) => `<path d="M${Array.from({length: 28}, (_, i) => pol(cx, cy, i % 2 ? r * .92 : r, i * Math.PI / 14)).join('L')}Z" fill="#6e4f1a"/><circle cx="${cx}" cy="${cy}" r="${n(r * .9)}" fill="#d9a21e"/><circle cx="${n(cx - r * .04)}" cy="${n(cy - r * .04)}" r="${n(r * .84)}" fill="#f3c534"/><circle cx="${n(cx - r * .14)}" cy="${n(cy - r * .14)}" r="${n(r * .5)}" fill="#fbe274" opacity=".8"/><path d="${ring(12, (i, a) => `M${pol(cx, cy, r * .24, a)}L${pol(cx, cy, r * .8, a)}`)}" stroke="#fdeca8" stroke-width="4" opacity=".7"/>${ring(14, (i, a) => `<circle cx="${n(cx + Math.cos(a) * r * .87)}" cy="${n(cy + Math.sin(a) * r * .87)}" r="${n(r * .03)}" fill="#8a5a1a"/>`)}<circle cx="${cx}" cy="${cy}" r="${n(r * .18)}" fill="#fcefb8"/>`;
