// Smooth closed outline through measured packshot points (quadratic curves through midpoints).
const blob = (p) => {
  const m = (a, b) => `${n((a[0] + b[0]) / 2)} ${n((a[1] + b[1]) / 2)}`;
  return `M${m(p[p.length - 1], p[0])}` + p.map((q, i) => `Q${q[0]} ${q[1]} ${m(q, p[(i + 1) % p.length])}`).join('') + 'Z';
};
// Blueberry: navy base, deep shadow side, dusty bloom highlight, dark crown.
const blueberry = (cx, cy, r, ca = -0.6) => {
  const kx = n(cx + Math.cos(ca) * r * .45), ky = n(cy + Math.sin(ca) * r * .45 - r * .1);
  return `<circle cx="${cx}" cy="${cy}" r="${r}" fill="#1c2652"/><circle cx="${n(cx - r * .07)}" cy="${n(cy - r * .07)}" r="${n(r * .9)}" fill="#45578f"/><ellipse cx="${n(cx - r * .22)}" cy="${n(cy - r * .24)}" rx="${n(r * .58)}" ry="${n(r * .48)}" fill="#97a8d6" opacity=".55"/><ellipse cx="${n(cx - r * .38)}" cy="${n(cy - r * .4)}" rx="${n(r * .16)}" ry="${n(r * .12)}" fill="#dfe6f6" opacity=".6"/><circle cx="${kx}" cy="${ky}" r="${n(r * .26)}" fill="#6d7fb4"/><path d="M${kx} ${n(ky - r * .22)}L${n(kx + r * .07)} ${n(ky - r * .06)}L${n(kx + r * .22)} ${ky}L${n(kx + r * .07)} ${n(ky + r * .06)}L${kx} ${n(ky + r * .22)}L${n(kx - r * .07)} ${n(ky + r * .06)}L${n(kx - r * .22)} ${ky}L${n(kx - r * .07)} ${n(ky - r * .06)}Z" fill="#141a3a"/>`;
};
// Apple wedge, a pointed crescent: dark skin edge, red skin, cream flesh face, flesh highlight, skin streak.
const appleWedge = (whole, skin, flesh, hi, streak) => `<path d="${whole}" fill="#8e1519"/><path d="${skin}" fill="#cf2d2c"/><path d="${streak}" stroke="#f2785e" stroke-width="5" fill="none" stroke-linecap="round" opacity=".75"/><path d="${flesh}" fill="#e6d4ab"/><path d="${hi}" fill="#f6eedb"/>`;
